static z_t3997_t z_t3997_create(uint64_t _capacity) {
    z_t3997_t _this = {0};
    if (_capacity > 0) {
        uint32_t _p2 = 8;
        while ((uint64_t)z_t3997_entries_cap(_p2) < _capacity && _p2 < 0x40000000u) {
            _p2 <<= 1;
        }
        _this.capacity = _p2;
        _this.entries = (z_t3997_entry_t*)z_xcalloc(
            z_t3997_entries_cap(_p2), sizeof(z_t3997_entry_t));
        if (_p2 > Z_T3997_SMALL_MAX) {
            _this.indices = (uint32_t*)z_xcalloc(_p2, sizeof(uint32_t));
        }
    }
    return _this;
}

/* Double the index and re-slot. `entries` is dense and stays in insertion
   order, so there is nothing to compact -- only the sparse index is rebuilt,
   and only once it is worth having. */
