    int64_t idx = z_t3997_find(_this, _key, NULL);
    z_t3887_t _r;
    if (idx >= 0) {
        _r.tag = Z_T3887_TAG_1;
        _r.data.a1 = _this->entries[idx].value;
    } else {
        _r.tag = Z_T3887_TAG_0;
    }
    return _r;
