    buf[len] = '\0';
#endif
    z_t61_t* boxed = (z_t61_t*)z_xmalloc(sizeof(z_t61_t));
    *boxed = z_t61_new(buf);
    out.tag = Z_T4328_TAG_1;
    out.data = boxed;
    return out;
